const items = $input.all();

const requiredFields = [
  "Date",
  "Salesperson_ID",
  "Salesperson_Name",
  "Region",
  "Target_Sales",
  "Actual_Sales",
  "Target_Orders",
  "Actual_Orders"
];

const validItems = [];
const invalidItems = [];

for (const item of items) {

  const data = item.json;

  const missingFields = requiredFields.filter(
    field =>
      data[field] === undefined ||
      data[field] === null ||
      String(data[field]).trim() === ""
  );

  if (missingFields.length === 0) {

    validItems.push(data);

  } else {

    invalidItems.push({
      salesperson_id: data.Salesperson_ID || "Unknown",
      missing_fields: missingFields
    });

  }
}

return [
  {
    json: {
      data_valid: invalidItems.length === 0,
      total_records: items.length,
      valid_records: validItems.length,
      invalid_records: invalidItems.length,
      invalid_details: invalidItems,
      sales_data: validItems
    }
  }
];

const data = $json.sales_data;

const results = [];

for (const item of data) {

  const targetSales = Number(item.Target_Sales);
  const actualSales = Number(item.Actual_Sales);

  const targetOrders = Number(item.Target_Orders);
  const actualOrders = Number(item.Actual_Orders);

  const salesAchievement =
    targetSales > 0
      ? (actualSales / targetSales) * 100
      : 0;

  const orderAchievement =
    targetOrders > 0
      ? (actualOrders / targetOrders) * 100
      : 0;

  const averageOrderValue =
    actualOrders > 0
      ? actualSales / actualOrders
      : 0;

  let performanceStatus;

  if (salesAchievement >= 100) {
    performanceStatus = "EXCEEDING";
  } else if (salesAchievement >= 90) {
    performanceStatus = "ON TRACK";
  } else if (salesAchievement >= 70) {
    performanceStatus = "AT RISK";
  } else {
    performanceStatus = "BELOW TARGET";
  }

  results.push({
    ...item,

    sales_achievement:
      Number(salesAchievement.toFixed(2)),

    order_achievement:
      Number(orderAchievement.toFixed(2)),

    average_order_value:
      Number(averageOrderValue.toFixed(2)),

    performance_status:
      performanceStatus
  });
}

return [
  {
    json: {
      sales_data: results
    }
  }
];

const data = $json;

let result = data.output;

if (typeof result !== "string") {
  result = JSON.stringify(result);
}

result = result
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(result);
} catch (error) {
  throw new Error("Invalid JSON returned by AI");
}

return {
  json: parsed
};
